function cloudStatus(tone,message){const el=$('saveStatus');if(!el)return;el.dataset.status=tone;el.innerHTML='<i></i> '+message+(tone==='error'?' <button type="button" class="sync-retry" data-act="retry-sync">TENTAR DE NOVO &#8635;</button>':'');const foot=$('footerSync');if(foot)foot.textContent=message;}
async function cloudCall(method,params='',body=null){
 if(!SUPABASE_URL||!SUPABASE_KEY)throw Error('Banco n&atilde;o conectado.');
 const url=SUPABASE_URL+'/rest/v1/copa_profiles'+params;
 const headers={'apikey':SUPABASE_KEY,'Accept':'application/json'};
 if(body!==null){headers['Content-Type']='application/json';headers['Prefer']='return=representation'}
 const response=await fetch(url,{method,headers,body:body===null?undefined:JSON.stringify(body),cache:'no-store',credentials:'omit'});
 if(!response.ok)throw Error('Nuvem indispon&iacute;vel: '+response.status);
 return response.status===204?[]:response.json();
}
function freshProfile(row){return {id:row.id,name:row.name,avatar:row.avatar,driveUrl:row.drive_url||ROOT_DRIVE,teacherMessage:row.teacher_message||'',journey:{onboarded:false,entries:[],counts:{},unlocked:{}},category:'outro',project:{title:'Meu vídeo',logline:'',mood:'',notes:'',nextStep:'',materialStatus:'none',seconds:0,steps:{},script:['','','','',''],updatedAt:Date.now()},xp:0,earned:{},badges:{},missions:{},quiz:{},focusSessions:0,avatarChoice:row.avatar??0,pinnedGuides:[],chat:[],createdAt:Date.now(),lastActive:Date.now()}}
function fromRow(row){const p=freshProfile(row);const state=row.state&&typeof row.state==='object'?row.state:{};
 for(const key of ['category','xp','earned','badges','missions','quiz','focusSessions','journey','avatarChoice','pinnedGuides'])if(state[key]!==undefined)p[key]=state[key];
 if(state.project&&typeof state.project==='object')p.project={...p.project,...state.project,steps:state.project.steps||{},script:Array.isArray(state.project.script)?state.project.script.slice(0,5):p.project.script};
 p.xp=clamp(p.xp,0,5000);p.focusSessions=clamp(p.focusSessions,0,1000);
 return p;
}
function toState(p){return {category:p.category,project:p.project,xp:p.xp,earned:p.earned,badges:p.badges,missions:p.missions,quiz:p.quiz,focusSessions:p.focusSessions,journey:p.journey,avatarChoice:p.avatarChoice,pinnedGuides:p.pinnedGuides}}
async function bootCloud(){
 const panel=$('gateActionPanel');
 if(!SUPABASE_URL||!SUPABASE_KEY){panel.innerHTML='<p class="cloud-unavailable"><b>Est&uacute;dio em prepara&ccedil;&atilde;o.</b> A sincroniza&ccedil;&atilde;o est&aacute; sendo configurada. Nenhum progresso ser&aacute; salvo apenas neste computador.</p>';return;}
 panel.innerHTML='<div class="loading-cloud"><span class="loading-spinner"></span> Buscando os est&uacute;dios da turma...</div>';
 try{
  const rows=await cloudCall('GET','?select=id,name,avatar,drive_url,active,state&order=name.asc');
  if(!Array.isArray(rows))throw Error('Resposta inesperada.');
  ROSTER.splice(0,ROSTER.length,...rows.map(r=>({id:r.id,name:r.name,avatar:r.avatar,avatarChoice:r.state?.avatarChoice??r.avatar,driveUrl:r.drive_url||ROOT_DRIVE})));
  for(const r of rows)store.profiles[r.id]=freshProfile(r);
  cloudConnected=true;renderGate();
 }catch(e){panel.innerHTML='<div class="cloud-unavailable"><b>N&atilde;o foi poss&iacute;vel abrir os est&uacute;dios.</b><p>Seu progresso n&atilde;o foi alterado. Confira a conex&atilde;o ou tente de novo.</p><button class="btn-secondary" data-act="retry-cloud">Tentar novamente &#8635;</button></div>';}
}
async function flushCloud(){
 if(!cloudConnected||!current)return;
 const p=getP();if(!p)return;
 const seq=changeNumber;
 if(acknowledgedNumber>=seq){try{await lastSave;return true}catch{return false}}
 const id=p.id,payload=toState(p);
 lastSave=lastSave.catch(()=>{}).then(async()=>{
  cloudStatus('saving','SALVANDO...');
  const rows=await cloudCall('PATCH','?id=eq.'+encodeURIComponent(id)+'&select=id',{state:payload});
  if(!Array.isArray(rows)||rows.length!==1)throw Error('N&atilde;o foi poss&iacute;vel confirmar a grava&ccedil;&atilde;o.');
  acknowledgedNumber=seq;
  cloudStatus('saved','SALVO NA NUVEM');
 });
 try{await lastSave;}catch(e){cloudStatus('error','FALHA AO SALVAR');toast('Falha ao salvar na nuvem. Confira a internet e tente novamente.');return false}
 if(changeNumber>seq){clearTimeout(savingTimer);savingTimer=setTimeout(()=>{void flushCloud()},300);}
 return true;
}
function scheduleCloudSave(){if(!cloudConnected)return;changeNumber++;clearTimeout(savingTimer);cloudStatus('saving','ALTERA&Ccedil;&Otilde;ES PENDENTES');savingTimer=setTimeout(()=>{void flushCloud()},850);}

