function norm(s){return String(s||'').replace(/<[^>]*>/g,' ').replace(/&[^;]{1,12};/g,' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim()}
const stopwords=new Set(['como','fazer','meu','minha','um','uma','no','na','de','do','da','para','pra','com','que','eu','quero','por','onde','tem','ficou','essa','isso','estou','ta','tudo','me','ajuda','video','videos','editar','edicao','seu','ele','ela','voce','isso']);
function searchGuides(q){let phrase=norm(q);const tokens=phrase.split(' ').filter(w=>w.length>2&&!stopwords.has(w));return guideData.map(g=>{const title=norm(g.title),cats=norm(g.category),tags=g.tags.map(norm),step=norm(g.steps.join(' '));let score=0;for(const t of tokens){if(title.includes(t))score+=5;if(cats.includes(t))score+=1.5;for(const tag of tags)if(tag===t)score+=10;else if(tag.includes(t)||t.includes(tag))score+=3;if(step.includes(t))score+=.4;}for(const tag of tags)if(tag.length>4&&phrase.includes(tag))score+=11;if(title.includes(phrase)&&phrase.length>4)score+=22;return {g,score}}).sort((a,b)=>b.score-a.score)}
window.COPA_MENTOR_TOOLS = Object.fromEntries(resources.map(r=>[r.id,r.url]));
function botAnswer(q,p,history=[]){return (window.CopaMentor?.answer(q,p,guideData,history))||{topic:'start',html:'Me conta o que voce esta tentando editar e onde travou.'}}
function sendChat(question){const p=getP();if(!p)return;const q=text(question).slice(0,260);if(!q)return;
 const history=p.chat.slice(-16), response=botAnswer(q,p,history);
 p.chat.push({who:'user',msg:q});p.chat.push({who:'bot',html:response.html,topic:response.topic});p.chat=p.chat.slice(-34);
 view='mentor';render();}

function openModal(kicker,title,markup){modalType=title;$('modalKicker').innerHTML=kicker;$('modalTitle').innerHTML=title;$('modalBody').innerHTML=markup;$('modalRoot').classList.remove('hidden');$('modalRoot').setAttribute('aria-hidden','false');document.body.classList.add('modal-open');let close=$('modalRoot').querySelector('[data-act="close-modal"]');if(close)close.focus()}
function closeModal(){$('modalRoot').classList.add('hidden');$('modalRoot').setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');modalType=''}
function openMission(id){const p=getP(),m=missions.find(x=>x.id===id);if(!p||!m)return;openModal('MISS&Atilde;O DO SEU V&Iacute;DEO',m.name,`<div class="chips" style="margin-bottom:21px"><span class="pill accent">TÉCNICA + XP</span><span class="pill">${m.time} MIN</span><span class="pill orange">${m.diff}</span></div><p class="modal-body-text">${m.desc}</p><div class="tool-output"><div class="card-kicker">SEU PLANO DE A&Ccedil;&Atilde;O</div><div class="modal-body-text"><ol>${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div></div><div class="soft-callout">N&atilde;o feche sua edi&ccedil;&atilde;o para cumprir esta miss&atilde;o. Fa&ccedil;a o desafio no seu pr&oacute;prio v&iacute;deo.</div><div class="modal-actions">${p.missions[id]?'<span class="pill accent">&#10003; MISS&Atilde;O CONCLU&Iacute;DA</span>':`<button class="btn-main" data-act="finish-mission" data-id="${id}">Registrar a técnica que testei ✓</button>`}<button class="btn-secondary" data-act="close-modal">Voltar para criar</button></div>`)}
function openGuide(id){const g=guideData.find(x=>x.id===id);if(!g)return;
 const d=window.COPA_GUIDE_DETAILS?.[id]||{};
 const prep=d.prep||'Abra seu video no CapCut ou separe um trecho para testar.';
 const steps=d.steps||g.steps;
 const errs=d.mistakes||['Nao tente mudar tudo de uma vez: ajuste um trecho e compare.','Se nao funcionar, volte ao original e tente outra ordem.'];
 const test=d.test||g.tip;
 const helper=d.ask||'Se nao funcionar, chama o Tio Ze ou um colega.';
 const where=d.why||g.tip;
 openModal(g.category,g.title,`<article class="real-guide"><p class="guide-intro">${safe(where)}</p><div class="guide-prep"><span>ANTES DE COME&Ccedil;AR</span><p>${safe(prep)}</p></div><div class="guide-section-head"><span>PASSO A PASSO</span><b>${steps.length} etapas</b></div><ol class="guide-steps">${steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${safe(s)}</p></li>`).join('')}</ol><div class="guide-columns"><div><h3>SE DER RUIM...</h3><ul>${errs.map(s=>`<li>${safe(s)}</li>`).join('')}</ul></div><div><h3>TESTE FINAL</h3><p>${safe(test)}</p></div></div><p class="guide-help">${safe(helper)}</p><div class="modal-actions"><button class="btn-secondary" data-act="pin-guide" data-id="${safe(g.id)}">${(getP()?.pinnedGuides||[]).includes(g.id)?'★ Fixado nos meus favoritos':'☆ Guardar este guia'}</button>${g.link?external(g.link,'Abrir '+getResource(g.link).name,'btn-main'):''}<button class="btn-secondary" data-act="ask-guide" data-question="${safe(g.title)}">Perguntar ao CineMentor &#10022;</button><button class="btn-quiet" data-act="close-modal">Fechar</button></div></article>`)}

function openFocus(){if(!focus.on&&focus.left===0)focus.left=12*60;let d=String(Math.floor(focus.left/60)).padStart(2,'0')+':'+String(focus.left%60).padStart(2,'0');openModal('MODO FOCO &middot; 12 MINUTOS','Uma cena por vez.',`<p class="modal-body-text">Escolha um &uacute;nico objetivo pequeno. N&atilde;o precisa terminar o v&iacute;deo: s&oacute; dar o pr&oacute;ximo passo.</p><div class="focus-box"><div><div class="card-kicker">SEU TEMPO DE CRIA&Ccedil;&Atilde;O</div><div id="focusDigits" class="focus-digit">${d}</div></div><span class="pill accent">SEM PRESS&Atilde;O</span></div><div class="modal-actions"><button class="btn-main" data-act="focus-toggle" id="focusToggle">${focus.on?'Pausar':'Come&ccedil;ar'} &#9654;</button><button class="btn-secondary" data-act="focus-reset">Reiniciar 12 min &#8635;</button>${focus.left===0?'<button class="btn-secondary" data-act="focus-finish">Registrar sess&atilde;o &#10003;</button>':''}</div><p class="link-warning">Dica: feche esta janela e continue editando. O rel&oacute;gio segue no navegador enquanto esta aba estiver aberta.</p>`);refreshFocus()}
function tickFocus(){if(!focus.on)return;let passed=Math.floor((Date.now()-focus.anchor)/1000);if(passed<=0)return;focus.left=Math.max(0,focus.left-passed);focus.anchor=Date.now();refreshFocus();if(focus.left===0){focus.on=false;clearInterval(focus.interval);focus.interval=null;toast('12 minutos conclu&iacute;dos. Voc&ecirc; criou algo hoje!');if(modalType==='Uma cena por vez.')openFocus()}}
function refreshFocus(){let el=$('focusDigits');if(el)el.textContent=String(Math.floor(focus.left/60)).padStart(2,'0')+':'+String(focus.left%60).padStart(2,'0');const b=$('focusToggle');if(b)b.innerHTML=focus.on?'Pausar &#10074;&#10074;':'Come&ccedil;ar &#9654;'}
function toggleFocus(){focus.on=!focus.on;if(focus.on){if(focus.left===0)focus.left=12*60;focus.anchor=Date.now();clearInterval(focus.interval);focus.interval=setInterval(tickFocus,350)}else{tickFocus();clearInterval(focus.interval);focus.interval=null}refreshFocus()}
function resetFocus(){focus.on=false;focus.left=12*60;clearInterval(focus.interval);focus.interval=null;refreshFocus();openFocus()}
function updateBPM(){if(view!=='lab'||labTab!=='rhythm')return;const bpm=metronome.bpm;[['bpm1',1],['bpm2',2],['bpm4',4]].forEach(([id,n])=>{if($(id))$(id).textContent=(n*60/bpm).toFixed(2)+'s'});if($('bpmDigit'))$('bpmDigit').textContent=bpm}
function stopMetronome(){if(metronome.interval){clearInterval(metronome.interval);metronome.interval=null}metronome.on=false}
function clickBeat(){const id=metronome.count++%4;for(let i=0;i<4;i++){const el=$('beat'+i);if(el)el.classList.toggle('active',i===id)}try{if(!metronome.audio)metronome.audio=new(window.AudioContext||window.webkitAudioContext)();const ctx=metronome.audio;if(ctx.state==='suspended')ctx.resume();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=id===0?650:510;gain.gain.setValueAtTime(.001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.018,ctx.currentTime+.008);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.075);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.08)}catch{}}
function toggleMetronome(){if(metronome.on){stopMetronome();render();return}metronome.on=true;metronome.count=0;clickBeat();metronome.interval=setInterval(clickBeat,60000/metronome.bpm);render();}
function generateIdea(){const p=getP();let d=ideaData[p.category]||ideaData.edit;let modes={surpresa:'Uma virada inesperada',epico:'Um momento gigante',humor:'Uma ideia para rir',emocao:'Algo para sentir',mist:'Um pequeno mist&eacute;rio'};ideaResult={title:modes[ideaMood]||'Uma ideia nova',hook:choose(d.hooks),middle:choose(d.middle),end:choose(d.finals),sound:choose(d.sounds)};render();}
function generateSuno(){const m={epic:'epic and triumphant',sad:'emotional and bittersweet',fun:'playful and upbeat',suspense:'mysterious and tense',calm:'gentle and dreamy',sports:'energetic and competitive'};const sty={cinematic:'cinematic film score',electronic:'modern electronic production',lofi:'warm lo-fi beats',rock:'energetic indie rock',orchestral:'orchestral film soundtrack'};const ins={piano:'expressive piano',drums:'punchy percussion',guitar:'electric guitar',synth:'atmospheric synthesizers',strings:'cinematic strings'};const p=getP(),genre=window.CopaPlanner.build(p).kind.name,voice=(p.category==='talk'||p.category==='gameplay');promptResult=`Instrumental soundtrack for a short ${genre} audiovisual project, ${m[sunoMood]}, ${sty[sunoStyle]}, featuring ${ins[sunoInstrument]}. Clear opening in the first 3 seconds, expressive build, intentional pause for a surprising moment, memorable but clean ending. ${voice?'Keep the arrangement light and sparse under dialogue and microphone voices.':'Make the beat easy to recognize so scene changes can follow musical accents.'} No vocals, no lyrics, coherent dynamics, 1 to 3 minutes.`;render()}
function copyText(s){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(s).then(()=>toast('Copiado! Agora &eacute; s&oacute; colar.')).catch(()=>fallbackCopy(s));}else fallbackCopy(s)}
function fallbackCopy(s){let a=document.createElement('textarea');a.value=s;a.style.position='fixed';a.style.opacity='0';document.body.appendChild(a);a.select();try{document.execCommand('copy');toast('Texto copiado!')}catch{toast('N&atilde;o consegui copiar; selecione o texto manualmente.')}a.remove()}
function ideaText(r){return `Copa Hollywood - ${r.title}\nComeco: ${htmlToText(r.hook)}\nMeio: ${htmlToText(r.middle)}\nFinal: ${htmlToText(r.end)}\nSom: ${htmlToText(r.sound)}`}
function htmlToText(str){const d=document.createElement('div');d.innerHTML=String(str||'');return d.textContent||''}
function openQuiz(){const p=getP();let index=(hash(p.id+dateKey())+Object.keys(p.quiz||{}).length)%quiz.length;showQuiz(index)}
function showQuiz(idx,choice=-1){const p=getP(),q=quiz[idx];let answered=choice>=0;openModal('CINEQUIZ &middot; DESAFIO R&Aacute;PIDO',`Voc&ecirc; faria esse corte?`,`<div class="question-card"><div class="card-kicker">CENA ${String(idx+1).padStart(2,'0')} / ${quiz.length}</div><h3>${q.q}</h3>${q.a.map((ans,i)=>`<button class="answer-button ${answered?(i===q.correct?'correct':i===choice?'wrong':''):''}" data-act="answer-quiz" data-q="${idx}" data-answer="${i}" ${answered?'disabled':''}>${String.fromCharCode(65+i)}. ${ans}</button>`).join('')}</div>${answered?`<div class="answer-feedback"><b style="color:var(--lime)">${choice===q.correct?'BOA!':'MAIS UMA TENTATIVA NO PR&Oacute;XIMO.'}</b><br>${q.why}</div><div class="modal-actions"><button class="btn-main" data-act="next-quiz" data-q="${idx}">Pr&oacute;xima pergunta &#8599;</button><button class="btn-secondary" data-act="close-modal">Voltar</button></div>`:`<p class="link-warning">N&atilde;o precisa decorar nada. Pense como quem est&aacute; editando.</p>`}`)}
