function finishMission(id){const p=getP(),m=missions.find(x=>x.id===id);if(!p||!m||p.missions[id])return;pendingMission=id;closeModal();go('journey');toast('Conta qual t\u00e9cnica voc\u00ea testou para registrar o desafio.');}
function openAvatarPicker(){const p=getP();if(!p)return;openModal('SEU AVATAR','Qual combina com você?',`<p class="modal-body-text">Escolhe um. Não precisa combinar com o seu vídeo.</p><div class="avatar-picker-row expanded">${window.CopaPlanner.AVATARS.map((av,i)=>`<button type="button" class="avatar-option ${Number(p.avatarChoice??p.avatar??0)===i?'selected':''}" data-act="pick-avatar" data-avatar="${i}" title="${safe(av.name)}" style="--avatar-color:${av.tone}">${av.icon}<small>${safe(av.name)}</small></button>`).join('')}</div>`)}
function openPlanAction(action,guideId){if(action==='category'){go('project');document.getElementById('filmCategory')?.focus();return;}if(action==='idea'){labTab='ideas';go('lab');return;}if(action==='technique'){go('journey');return;}if(action==='capcut'){window.open('https://www.capcut.com/pt-br/tools/online-video-editor','_blank','noopener,noreferrer');return;}if(action==='feedback'){go('mentor');sendChat('Como testar se meu vídeo funciona com um colega?');return;}if(action==='assembly'||action==='material'||action==='drive'||action==='research'||action==='export'){openGuide(guideId||'start');return;}go('mentor');}
